package org.achievementlabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.util.Base64;import androidx.webkit.WebViewAssetLoader;
import org.json.*;import java.io.*;import java.time.Instant;import java.util.concurrent.*;

public final class Xbox360Activity extends Activity {
 private WebView web;private Profile360Store store;private final ExecutorService files=Executors.newSingleThreadExecutor();private String picker;private byte[] exporting;private boolean closing;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(0xff081218);store=new Profile360Store(new File(getFilesDir(),"xbox360"));web=new WebView(this);web.setBackgroundColor(0xff081218);android.widget.FrameLayout host=new android.widget.FrameLayout(this);host.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));setContentView(host);if(Build.VERSION.SDK_INT>=35){host.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout()),ime=insets.getInsets(android.view.WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));return android.view.WindowInsets.CONSUMED;});host.requestApplyInsets();}
  WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
  if(BuildConfig.DEBUG&&getIntent().getBooleanExtra("selfTest",false))web.setWebChromeClient(new WebChromeClient(){@Override public boolean onConsoleMessage(ConsoleMessage m){android.util.Log.i("Labs360Test",m.message()+" line "+m.lineNumber());return true;}});
  WebViewAssetLoader assets=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
  web.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String url){v.evaluateJavascript("(()=>{if(document.getElementById('globalScan'))return;const b=document.createElement('button');b.id='globalScan';b.textContent='Scan QR';b.setAttribute('aria-label','Scan QR codes');b.onclick=()=>Labs360Native.call('globalScan','scan','{}');document.querySelector('header').appendChild(b);})()",null);files.execute(()->{try{JSONObject config=appearance();runOnUiThread(()->v.evaluateJavascript("window.setLabsAppearance("+config+")",null));}catch(Exception ignored){}});if(BuildConfig.DEBUG&&getIntent().getBooleanExtra("selfTest",false))v.evaluateJavascript("window.mobile360SelfTest()",null);}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){WebResourceResponse local=assets.shouldInterceptRequest(r.getUrl());if(local!=null)return local;String host=r.getUrl().getHost();if(!r.isForMainFrame()&&"https".equals(r.getUrl().getScheme())&&host!=null&&(host.endsWith(".xboxlive.com")||host.equals("store-images.s-microsoft.com")))return null;return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}});
  web.addJavascriptInterface(new Bridge(),"Labs360Native");web.loadUrl("https://appassets.androidplatform.net/assets/xbox360/index.html");
 }
 private void reply(String id,Object result,String error){runOnUiThread(()->{if(!closing&&web!=null)web.evaluateJavascript("window.native360Result("+JSONObject.quote(id)+","+(result==null?"null":result.toString())+","+(error==null?"null":JSONObject.quote(error))+")",null);});}
 private JSONObject appearance()throws Exception{SessionEngine e=engine();JSONObject config=new JSONObject();for(String key:new String[]{"glassEnabled","oledMode","glassTint","accentColour","glassTransparency","glassBlur","backgroundSource","persistentGameArt","artworkFit","backgroundDim","backgroundBlur"})if(e.prefs.has(key))config.put(key,e.prefs.get(key));if("custom".equals(config.optString("backgroundSource"))){File file=new File(getFilesDir(),"custom-background.jpg");if(file.exists())config.put("customImage","data:image/jpeg;base64,"+Base64.encodeToString(Profile360Store.bounded(new FileInputStream(file),16*1024*1024),Base64.NO_WRAP));}else{String title=e.prefs.optString("backgroundTitle");for(int i=0;i<e.games.length();i++){JSONObject g=e.games.getJSONObject(i);if(title.equals(g.optString("titleId")))config.put("backgroundURL",StoreArtwork.secure(g.optString("displayImage")));}}return config;}
 private JSONObject empty(){return new JSONObject();}
 private SessionEngine engine()throws Exception{SessionEngine e=((LabsApplication)getApplication()).peekEngine();if(e==null)throw new Exception("Connect an Xbox account in Settings first.");return e;}
 final class Bridge {
  @JavascriptInterface public void call(String id,String action,String json){if(id.length()>32||json.length()>50000)return;files.execute(()->{try{JSONObject p=new JSONObject(json);Object result;
   switch(action){
    case "scan":runOnUiThread(()->startActivityForResult(new Intent(this,ScanActivity.class),24));result=empty();break;
    case "testProfile":if(!BuildConfig.DEBUG||!getIntent().getBooleanExtra("selfTest",false))throw new Exception("Test mode is unavailable.");store.load(Profile360Store.bounded(getAssets().open("xbox360/synthetic.dat"),Profile360Store.LIMIT));result=new JSONObject().put("length",store.working.length);break;
    case "testDone":if(!BuildConfig.DEBUG||!getIntent().getBooleanExtra("selfTest",false))throw new Exception("Test mode is unavailable.");if(p.optBoolean("passed")){if(java.util.Arrays.equals(store.export(true),store.export(false)))throw new Exception("Test output unchanged.");}Profile360Store.atomic(new File(getFilesDir(),"xbox360-self-test.json"),p.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));result=empty();break;
    case "pickProfile":case "pickReference":{runOnUiThread(()->{if(picker!=null){reply(id,null,"A document picker is already open.");return;}picker=id;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),action.equals("pickProfile")?10:11);});return;}
    case "identity":result=new JSONObject().put("base64",Base64.encodeToString(Profile360Store.bounded(getAssets().open("xbox360/signing.dat"),556),Base64.NO_WRAP));break;
    case "readChunk":{int offset=p.getInt("offset");if(store.working==null||offset<0||offset>=store.working.length)throw new Exception("Invalid profile chunk.");result=new JSONObject().put("base64",Base64.encodeToString(store.working,offset,Math.min(Profile360Store.CHUNK,store.working.length-offset),Base64.NO_WRAP));break;}
    case "beginSave":store.begin(p.getInt("length"),p.getString("sha1"),p.getString("before"));result=empty();break;
    case "saveChunk":store.append(p.getInt("offset"),Base64.decode(p.getString("base64"),Base64.NO_WRAP));result=empty();break;
    case "commitSave":store.commit();result=empty();break;
    case "abortSave":store.abort();result=empty();break;
    case "export":{boolean backup=p.optBoolean("original");byte[] bytes=store.export(backup);String name=Profile360Store.profileName(bytes)+(backup?".original.bak":"");runOnUiThread(()->{if(picker!=null){reply(id,null,"A document picker is already open.");return;}picker=id;exporting=bytes;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),12);});return;}
    case "art":{SessionEngine e=engine();String url="",title=p.getString("titleId");for(int i=0;i<e.games.length();i++){JSONObject g=e.games.getJSONObject(i);if(title.equals(g.optString("titleId"))){url=g.optString("displayImage");break;}}if(!url.startsWith("https://"))url="";result=new JSONObject().put("url",url);if(!BuildConfig.DEBUG||!getIntent().getBooleanExtra("selfTest",false)){try{((JSONObject)result).put("images",StoreArtwork.lookup(title));}catch(Exception ignored){}}break;}
    case "reference":{SessionEngine e=engine();JSONObject account=new JSONObject(e.auth().toString());String title=Core.numeric(p.getString("titleId")),tag=p.getString("gamertag").trim();if(tag.isEmpty()||tag.length()>64)throw new Exception("Enter an Xbox gamertag.");JSONObject user=Net.xbox("https://profile.xboxlive.com/users/gt("+Net.enc(tag)+")/profile/settings?settings=Gamertag",account.getString("authorization"),"2","GET",null).getJSONArray("profileUsers").getJSONObject(0);JSONArray raw=Net.achievements(account,new JSONObject().put("titleId",title).put("devices",new JSONArray().put("Xbox360")),Core.numeric(user.getString("id"))),rows=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject r=raw.getJSONObject(i);if(!title.equals(String.valueOf(r.opt("titleId")))||!r.optBoolean("unlocked"))continue;boolean online=r.optBoolean("unlockedOnline");Object time=JSONObject.NULL;if(online)try{time=Instant.parse(r.getString("timeUnlocked")).toEpochMilli();}catch(Exception ignored){continue;}rows.put(new JSONObject().put("id",Long.parseLong(Core.numeric(r.getString("id")))).put("titleId",title).put("score",r.getInt("gamerscore")).put("unlocked",true).put("online",online).put("time",time));}result=new JSONObject().put("rows",rows);break;}
    default:throw new Exception("Unsupported Xbox 360 command.");
   }reply(id,result,null);
  }catch(Exception error){if(BuildConfig.DEBUG&&getIntent().getBooleanExtra("selfTest",false))android.util.Log.e("Labs360Test",action+": "+error.getClass().getSimpleName()+": "+error.getMessage());reply(id,null,error.getMessage()==null?"Xbox 360 operation failed.":error.getMessage());}});}
 }
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==24){if(result==RESULT_OK){JSONObject qr=MainActivity.pendingQR;MainActivity.pendingQR=null;if(qr!=null)try{QRScanImport.accept(this,engine(),qr);}catch(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton("Close",null).show();}}return;}String id=picker;picker=null;if(id==null)return;if(result!=RESULT_OK||data==null||data.getData()==null){exporting=null;try{reply(id,new JSONObject().put("cancelled",true),null);}catch(Exception ignored){}return;}byte[] output=exporting;exporting=null;files.execute(()->{try{JSONObject response;if(request==12){if(output==null)throw new IOException("No signed profile available.");try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new IOException("Could not create export.");out.write(output);}byte[] readback=Profile360Store.bounded(getContentResolver().openInputStream(data.getData()),Profile360Store.LIMIT);if(!java.util.Arrays.equals(output,readback))throw new IOException("Export readback failed. Private verified copy and backups are retained.");response=empty();}else if(request==10){byte[] bytes=Profile360Store.bounded(getContentResolver().openInputStream(data.getData()),Profile360Store.LIMIT);store.load(bytes);response=new JSONObject().put("length",bytes.length);}else{byte[] text=Profile360Store.bounded(getContentResolver().openInputStream(data.getData()),2*1024*1024);response=new JSONObject().put("text",new String(text,java.nio.charset.StandardCharsets.UTF_8));}reply(id,response,null);}catch(Exception error){reply(id,null,error.getMessage());}});}
 @Override protected void onDestroy(){closing=true;if(web!=null){web.removeJavascriptInterface("Labs360Native");web.destroy();web=null;}files.shutdown();super.onDestroy();}
}
